    "reading": "高台之上，一位手持三重十字杖的长者正在为面前两位下跪的信徒赐福，两把交叉的金色钥匙静置在脚前。这张牌描绘的是被传统、教义和集体规范所承载的经验传递。它关切的是一个人如何在已有的知识体系里找到自己的位置，以及那条被前人走过无数次的路是否还通往他真正想去的地方。生活里，它对应上学、考证、拜师学艺，也对应那些你从小到大被教会却从未认真审视过的“应该”。"
