    "reading": "伊甸园中，亚当与夏娃赤诚相对，两人之间耸立着一座火山，头顶天使拉斐尔张开双翼。这张牌描绘的与其说是浪漫，不如说是站在路口时价值观的自我暴露：一个选择一旦做出，就会像镜子一样照出你真正在意什么。它关切的是吸引、承诺与决断交织在一起的那个瞬间。生活里，它对应那些需要你对自己诚实的选择，不是选哪个更好，而是选完之后你能不能在那个倒影里认出自己。"
