        "展开": "月亮式的觉察是跟模糊共处，不需要今天就把一切搞明白。选一件你反复纠结的事，先不分析它，让它在雾里多待一会儿。不驱散，不诅咒。今天你不需要答案，你需要的是忍受\"暂时没有答案\"的能力。那条模糊的小径今天不走，也还在。",
