    "reading": "一轮诡异的三层月亮高悬夜空，月光微弱地洒向一条穿过两座灰色石塔的未知小径，池塘边一只龙虾正从水底爬出，家犬与野狼同时仰头吠叫。这张牌描绘的是理性光线不足时的内心地貌，那些白天被压制住的恐惧、模糊的直觉和未被命名的感受在暗中浮了出来。它关切的是一个人在看不清楚的路上如何继续行走。生活里，它对应半夜醒来之后再也睡不着的胡思乱想，一次在信息不全时依然要做的决定。"
