    "reading": "大雪纷飞的冬夜里，两个衣衫褴褛的乞丐拄着拐杖步履蹒跚地走过，他们身后就是一扇明亮的刻有钱币图案的教堂彩绘玻璃窗，但他们低着头完全没有看到。这张牌描绘的是物质与身体层面的匮乏感，不仅是口袋里少了什么，更是精神上也同时陷入了被遗弃的寒冷。它关切的是一个人在感到匮乏的时候有没有转过身去看一眼那扇一直亮着的窗。生活里，它对应一段入不敷出的拮据期，或是在最艰难的时候拒绝了本来愿意帮忙的朋友，因为觉得开口求助就等于承认失败。"
